import "dart:convert";
import "dart:io";

import "package:flutter/material.dart";
import "package:flutter_test/flutter_test.dart";
import "package:melody/ui/shared/theme.dart";
import "package:melody/ui/shared/widgets.dart";

/// The bundled icons are generated by tools/build/icons.py from icon_colors.json;
/// these keep that table in step with the theme, and every platform on one icon.
void main() {
  String hex(Color color) =>
      "#${(color.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, "0")}"
          .toUpperCase();

  test("icon_colors.json holds BrandMark's default light colors", () {
    final scheme = buildTheme("violet", Brightness.light).colorScheme;
    expect(
      jsonDecode(File("../tools/build/icon_colors.json").readAsStringSync()),
      [for (final color in brandMarkColors(scheme)) hex(color)],
      reason: "run tools/build/icons.py after updating",
    );
    expect(
      scheme.onPrimary,
      Colors.white,
      reason: "the generated foreground glyph is white",
    );
  });

  test("Android has one launcher entry, on the activity itself", () {
    final manifest = File(
      "android/app/src/main/AndroidManifest.xml",
    ).readAsStringSync();
    expect(manifest, isNot(contains("activity-alias")));
    expect(
      RegExp("android.intent.category.LAUNCHER").allMatches(manifest),
      hasLength(1),
    );
    expect(manifest, contains('android:icon="@mipmap/ic_launcher"'));
  });

  test("the Linux bundle has the window icon", () {
    expect(File("linux/runner/resources/app_icon.png").existsSync(), isTrue);
    expect(
      File("linux/CMakeLists.txt").readAsStringSync(),
      contains("runner/resources/app_icon.png"),
    );
  });
}
